parameters.jsCode:
// The same instruction the Telegram bot uses, so a summary reads the same
// whichever way the article arrived. Improving it is Mikko's part.
return { json: {
  task: 'summarise',
  item_id: $json.id,
  system_prompt: 'Tiivistä seuraava uutinen jäsenkirjeeseen kolmella lyhyellä suomenkielisellä lauseella. Kerro vain se mitä tekstissä lukee. Älä keksi mitään lisää.',
  user_text: `${$json.title}\n\n${$json.raw_text}`,
} };
